CREATE OR REPLACE FUNCTION private.announce_throws(p_round uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  rec public.encounter_players%ROWTYPE;
  who text;
  line text;
  last_line text;
BEGIN
  FOR rec IN
    SELECT ep.*
    FROM public.encounter_players ep
    WHERE ep.round_id = p_round
      AND ep.ball IS NOT NULL
      AND ep.throw_processed = false
    ORDER BY coalesce(private.trainer_label(ep.user_id), 'Trainer'), ep.user_id
    FOR UPDATE
  LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    IF rec.result_reason IS DISTINCT FROM 'standard_throw' THEN
      BEGIN
        PERFORM private.spend_bag_item(rec.user_id, rec.ball);
      EXCEPTION
        WHEN SQLSTATE 'NB001' THEN
          UPDATE public.encounter_players ep
            SET throw_processed = true, result_reason = 'no_ball_left'
            WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
          INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
          SELECT p_round, rec.user_id, who, 'timeout', rec.ball,
                 '⌛ ' || who || ' ran out of ' || private.item_label(rec.ball) || 's before the throw.'
          WHERE NOT EXISTS (
            SELECT 1 FROM public.play_console_log l
            WHERE l.round_id = p_round AND l.user_id = rec.user_id AND l.kind = 'timeout'
          )
          ON CONFLICT DO NOTHING;
          CONTINUE;
      END;
    END IF;
    UPDATE public.encounter_players ep
      SET throw_processed = true
      WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
    line := who || ' has thrown ' || private.a_or_an(private.item_label(rec.ball)) || '!';
    PERFORM private.log_activity(p_round, rec.user_id, 'threw', rec.ball);
    UPDATE public.play_console_log l
      SET message = line
      WHERE l.round_id = p_round
        AND l.user_id = rec.user_id
        AND l.kind = 'threw'
        AND coalesce(l.message, '') = '';
    last_line := line;
  END LOOP;

  FOR rec IN
    SELECT ep.*
    FROM public.encounter_players ep
    WHERE ep.round_id = p_round AND ep.ball IS NULL AND ep.result IS NULL
  LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
    SELECT p_round, rec.user_id, who, 'timeout', NULL,
           '⌛ ' || who || ' did not choose a Poké Ball in time.'
    WHERE NOT EXISTS (
      SELECT 1 FROM public.play_console_log l
      WHERE l.round_id = p_round AND l.user_id = rec.user_id AND l.kind = 'timeout'
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  RETURN last_line;
END;
$function$

CREATE OR REPLACE FUNCTION private.materialize_streamlink_catch(p_user_id uuid, p_form_id integer, p_level integer, p_ctx text, p_source_key text, p_ball text DEFAULT 'poke'::text, p_round_id uuid DEFAULT NULL::uuid, p_shiny boolean DEFAULT false, p_content_build text DEFAULT 'sl-ref-20261013-227b573'::text, p_hidden_ticket text DEFAULT NULL::text, p_variant text DEFAULT 'normal'::text, p_name text DEFAULT NULL::text, p_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_dex int;
  v_name text;
  inserted uuid;
  v_public text;
BEGIN
  IF private.streamlink_wire_is_enabled() THEN
    RETURN private.persist_streamlink_catch(
      p_user_id, p_form_id, p_level, p_ctx, p_source_key, p_ball, p_round_id,
      p_shiny, p_content_build, p_hidden_ticket, p_variant, p_name, p_gender
    );
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-user'), 'path', 'stamp');
  END IF;
  IF p_ctx IS NULL OR p_ctx NOT IN ('catch', 'grant', 'event') THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-ctx'), 'path', 'stamp');
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-source-key'), 'path', 'stamp');
  END IF;
  IF p_ctx IN ('grant', 'event') AND private.streamlink_protected_trainer(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('protected-trainer'), 'path', 'stamp');
  END IF;

  SELECT f.dex, initcap(replace(s.slug, '-', ' '))
    INTO v_dex, v_name
  FROM private.ref_forms f
  JOIN private.ref_species s
    ON s.content_build = f.content_build AND s.dex = f.dex
  WHERE f.content_build = coalesce(p_content_build, 'sl-ref-20261013-227b573')
    AND f.form_id = p_form_id;
  v_dex := coalesce(v_dex, p_form_id);
  v_name := coalesce(nullif(btrim(p_name), ''), v_name, 'Pokemon');

  BEGIN
    INSERT INTO public.catches (
      user_id, dex, name, variant, gender, ball, round_id, source_key, level, pokemon_form_id
    ) VALUES (
      p_user_id,
      v_dex,
      v_name,
      coalesce(nullif(btrim(p_variant), ''), 'normal'),
      coalesce(nullif(btrim(p_gender), ''), 'M'),
      coalesce(nullif(btrim(p_ball), ''), 'poke'),
      p_round_id,
      p_source_key,
      p_level,
      p_form_id
    )
    RETURNING id, public_id INTO inserted, v_public;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array('already-settled'),
      'replay', true,
      'path', 'stamp'
    );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'catchId', inserted,
    'publicId', v_public,
    'path', 'stamp'
  );
END
$function$

CREATE OR REPLACE FUNCTION private.persist_streamlink_catch(p_user_id uuid, p_form_id integer, p_level integer, p_ctx text, p_source_key text, p_ball text DEFAULT 'poke'::text, p_round_id uuid DEFAULT NULL::uuid, p_shiny boolean DEFAULT false, p_content_build text DEFAULT 'sl-ref-20261013-227b573'::text, p_hidden_ticket text DEFAULT NULL::text, p_variant text DEFAULT 'normal'::text, p_name text DEFAULT NULL::text, p_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  catch_id uuid;
  prep jsonb;
  mon jsonb;
  legal jsonb;
  ticket_uuid uuid;
  v_name text;
  v_variant text;
  v_public text;
  legacy text[];
  inserted uuid;
BEGIN
  IF NOT private.streamlink_wire_is_enabled() THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('wire-disabled'), 'path', 'stamp');
  END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-user'));
  END IF;
  IF p_ctx IS NULL OR p_ctx NOT IN ('catch', 'grant', 'event') THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-ctx'));
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-source-key'));
  END IF;
  IF p_ctx = 'catch' AND p_source_key NOT LIKE 'play:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx = 'grant' AND p_source_key NOT LIKE 'grant:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx = 'event' AND p_source_key NOT LIKE 'event:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx IN ('grant', 'event') AND private.streamlink_protected_trainer(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('protected-trainer'));
  END IF;

  catch_id := gen_random_uuid();
  prep := private.streamlink_generate_prepare(
    p_form_id, p_level, p_ctx, coalesce(p_content_build, 'sl-ref-20261013-227b573'), p_hidden_ticket
  );
  IF (prep->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN prep;
  END IF;

  mon := private.streamlink_complete_and_bind(
    prep,
    coalesce(p_shiny, false),
    (private.streamlink_secure_u32() % 25)::int + 1,
    (private.streamlink_secure_u32() % 2147483647)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    private.streamlink_secure_u32(),
    catch_id
  );
  IF (mon->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN mon;
  END IF;

  IF (prep->>'ticketUuid') IS NOT NULL AND btrim(prep->>'ticketUuid') <> '' THEN
    ticket_uuid := (prep->>'ticketUuid')::uuid;
  END IF;
  legal := private.assert_streamlink_legal(mon, p_ctx, ticket_uuid);
  IF (legal->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN legal;
  END IF;

  SELECT initcap(replace(s.slug, '-', ' '))
    INTO v_name
  FROM private.ref_species s
  WHERE s.content_build = prep->>'build'
    AND s.dex = private.streamlink_json_int(prep->'dex');
  v_name := coalesce(nullif(btrim(p_name), ''), v_name, 'Pokemon');
  v_variant := CASE
    WHEN coalesce(p_shiny, false) THEN 'shiny'
    ELSE coalesce(nullif(btrim(p_variant), ''), 'normal')
  END;
  v_public := private.streamlink_next_public_id('SL');
  SELECT coalesce(array_agg(x), ARRAY[]::text[])
    INTO legacy
  FROM jsonb_array_elements_text(mon->'legacyMoves') x;

  BEGIN
    INSERT INTO public.catches (
      id, user_id, dex, name, variant, gender, ball, round_id, source_key,
      public_id, level, pokemon_form_id,
      iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
      av_hp, av_atk, av_def, av_spa, av_spd, av_spe,
      moves, friendship, height_m, weight_kg,
      nature_id, ability_id, ability_slot,
      ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
      move_slots, ruleset_id, content_build,
      hp_current, hp_max, status, held_item, gigantamax_factor
    ) VALUES (
      catch_id,
      p_user_id,
      private.streamlink_json_int(mon->'dex'),
      v_name,
      v_variant,
      coalesce(nullif(btrim(p_gender), ''), mon->>'gender'),
      coalesce(nullif(btrim(p_ball), ''), 'poke'),
      p_round_id,
      p_source_key,
      v_public,
      private.streamlink_json_int(mon->'level'),
      private.streamlink_json_int(mon->'formId'),
      private.streamlink_json_int(mon#>'{ivs,hp}'),
      private.streamlink_json_int(mon#>'{ivs,atk}'),
      private.streamlink_json_int(mon#>'{ivs,def}'),
      private.streamlink_json_int(mon#>'{ivs,spa}'),
      private.streamlink_json_int(mon#>'{ivs,spd}'),
      private.streamlink_json_int(mon#>'{ivs,spe}'),
      0, 0, 0, 0, 0, 0,
      legacy,
      private.streamlink_json_int(mon->'friendship'),
      (mon->>'heightM')::numeric,
      (mon->>'weightKg')::numeric,
      private.streamlink_json_int(mon->'natureId'),
      private.streamlink_json_int(mon->'abilityId'),
      mon->>'abilitySlot',
      0, 0, 0, 0, 0, 0,
      mon->'moveSlots',
      mon->>'rulesetId',
      mon->>'contentBuild',
      private.streamlink_json_int(mon->'hpCurrent'),
      private.streamlink_json_int(mon->'hpMax'),
      NULL,
      NULL,
      false
    )
    RETURNING id INTO inserted;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array('already-settled'),
      'replay', true,
      'path', 'wire'
    );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'catchId', inserted,
    'publicId', v_public,
    'path', 'wire',
    'mon', mon
  );
END
$function$

CREATE OR REPLACE FUNCTION private.settle_if_needed(r encounter_rounds)
 RETURNS encounter_rounds
 LANGUAGE plpgsql
AS $function$
DECLARE
  rec public.encounter_players%ROWTYPE;
  cfg jsonb;
  calc jsonb;
  bait_count int;
  player_count int;
  owns boolean;
  v_odds numeric;
  v_roll numeric;
  v_caught boolean;
  pending boolean;
  clk timestamptz;
  join_at timestamptz;
  prepare_at timestamptz;
  throw_at timestamptz;
  reveal_at timestamptz;
  throw_line text;
  who text;
  species text;
  test_out text;
  form_id int;
  v_level int;
  v_mat jsonb;
  v_catch_id uuid;
  v_life text;
BEGIN
  IF r IS NULL OR r.cancelled THEN RETURN r; END IF;
  IF r.paused_at IS NOT NULL THEN RETURN r; END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended(r.id::text, 0)) THEN RETURN r; END IF;
  SELECT * INTO r FROM public.encounter_rounds WHERE id = r.id;
  IF r IS NULL OR r.cancelled OR r.paused_at IS NOT NULL THEN RETURN r; END IF;
  SELECT EXISTS (SELECT 1 FROM public.encounter_players ep WHERE ep.round_id = r.id AND ep.result IS NULL) INTO pending;
  IF pending = false AND r.resolved THEN RETURN r; END IF;
  clk := now();
  form_id := private.canonical_form_id(r.dex, coalesce(r.pokemon_form_id, r.dex));
  species := coalesce(nullif(btrim(r.name), ''), private.form_display_name(r.dex, form_id), 'the Pokémon');
  IF r.deadlines IS NOT NULL THEN
    join_at := (r.deadlines->>'join')::timestamptz;
    prepare_at := (r.deadlines->>'prepare')::timestamptz;
    throw_at := coalesce((r.deadlines->>'throw')::timestamptz, (r.deadlines->>'reveal')::timestamptz);
    reveal_at := (r.deadlines->>'reveal')::timestamptz;
  END IF;
  IF join_at IS NOT NULL AND clk >= join_at THEN
    IF NOT EXISTS (SELECT 1 FROM public.encounter_players WHERE round_id = r.id) THEN
      INSERT INTO public.play_console_log (round_id, kind, message)
      SELECT r.id, 'cancelled', 'No Trainers joined the encounter. The wild ' || species || ' wandered away!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.kind = 'cancelled')
      ON CONFLICT DO NOTHING;
      UPDATE public.encounter_rounds SET cancelled = true, hidden = true, phase = 'closed', resolved = true, paused_at = null,
        last_action = 'No Trainers joined. The wild ' || species || ' wandered away!', updated_at = now() WHERE id = r.id RETURNING * INTO r;
      RETURN r;
    END IF;
    PERFORM private.phase_banner(r.id, 'prepare', 'Trainers are preparing their items…');
  END IF;
  IF prepare_at IS NOT NULL AND clk >= prepare_at THEN
    PERFORM private.phase_banner(r.id, 'throw', 'Trainers are choosing their Poké Balls!');
  END IF;
  IF r.deadlines IS NOT NULL THEN
    IF throw_at IS NOT NULL AND clk < throw_at THEN RETURN r; END IF;
  ELSIF private.round_phase(r) IN ('join', 'prepare', 'throw') THEN
    RETURN r;
  END IF;
  throw_line := private.announce_throws(r.id);
  IF throw_line IS NOT NULL THEN
    UPDATE public.encounter_rounds SET last_action = throw_line, updated_at = now() WHERE id = r.id RETURNING * INTO r;
  END IF;
  IF reveal_at IS NOT NULL AND clk < reveal_at THEN RETURN r; END IF;
  IF r.deadlines IS NULL AND private.round_phase(r) = 'reveal' THEN RETURN r; END IF;
  cfg := private.capture_config();
  test_out := CASE
    WHEN coalesce(r.trigger_source, '') = 'TEST' THEN nullif(btrim(coalesce(r.rules->>'testOutcome', '')), '')
    ELSE NULL
  END;
  SELECT count(*)::int, count(*) FILTER (WHERE prep = 'bait')::int INTO player_count, bait_count FROM public.encounter_players WHERE round_id = r.id;
  FOR rec IN SELECT * FROM public.encounter_players WHERE round_id = r.id AND result IS NULL FOR UPDATE LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    IF rec.ball IS NULL OR rec.result_reason = 'no_ball_left' THEN
      UPDATE public.encounter_players ep SET result = 'No throw', caught = false, result_reason = coalesce(ep.result_reason, 'no_ball')
      WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
      CONTINUE;
    END IF;
    SELECT EXISTS (SELECT 1 FROM public.catches c WHERE c.user_id = rec.user_id AND c.dex = r.dex) INTO owns;
    cfg := private.capture_config() || jsonb_build_object(
      '_context', private.capture_throw_context(r, rec.user_id, rec.ball_at)
    );
    calc := private.capture_chance(r.dex, rec.ball, CASE WHEN rec.prep = 'bait' THEN NULL ELSE rec.prep END, bait_count, player_count, rec.prep = 'bait', owns, private.variant_is_shiny(r.variant), 1.0, clk, cfg);
    v_odds := (calc->>'finalChance')::numeric;
    IF test_out = 'catch' THEN
      v_roll := 0; v_caught := true;
    ELSIF test_out = 'escape' THEN
      v_roll := 1; v_caught := false;
    ELSIF coalesce((calc->>'guaranteed')::boolean, false) THEN
      v_roll := 0; v_caught := true;
    ELSE
      v_roll := private.secure_random(); v_caught := v_roll < v_odds;
    END IF;
    UPDATE public.encounter_players ep SET chance = v_odds, roll = v_roll, caught = v_caught, result = CASE WHEN v_caught THEN 'Caught' ELSE 'Escaped' END, result_reason = CASE WHEN v_caught THEN 'caught' ELSE 'escaped' END WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
    INSERT INTO public.capture_log (round_id, user_id, dex, species_name, variant, gender, is_shiny, is_female, canonical_catch_rate, base_chance, ball_key, ball_multiplier, ball_condition_met, berry_key, berry_multiplier, honey_contributors, honey_participants, honey_multiplier, honey_contributor_multiplier, shiny_multiplier, event_multiplier, other_multiplier, raw_chance, final_chance, capture_roll, success, detail)
    VALUES (r.id, rec.user_id, r.dex, r.name, r.variant, r.gender, private.variant_is_shiny(r.variant), r.gender = 'Female', (calc->>'catchRate')::int, (calc->>'baseChance')::numeric, calc->'ball'->>'key', (calc->'ball'->>'multiplier')::numeric, (calc->'ball'->>'conditionMet')::boolean, calc->'berry'->>'key', (calc->'berry'->>'multiplier')::numeric, (calc->'honey'->>'contributors')::int, (calc->'honey'->>'participants')::int, (calc->'honey'->>'multiplier')::numeric, (calc->>'honeyContributorMultiplier')::numeric, (calc->>'shinyMultiplier')::numeric, (calc->>'eventMultiplier')::numeric, (calc->>'otherMultiplier')::numeric, (calc->>'rawChance')::numeric, v_odds, v_roll, v_caught, calc || jsonb_build_object('testOutcome', test_out, 'formId', form_id))
    ON CONFLICT (round_id, user_id) DO NOTHING;
    IF v_caught THEN
      INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
      SELECT r.id, rec.user_id, who, 'caught', species, '⭐ ' || who || ' caught ' || species || '!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.user_id = rec.user_id AND l.kind = 'caught') ON CONFLICT DO NOTHING;
    ELSE
      INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
      SELECT r.id, rec.user_id, who, 'escaped', species, '✖ ' || who || ' was unable to catch ' || species || '. Better luck next encounter!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.user_id = rec.user_id AND l.kind = 'escaped') ON CONFLICT DO NOTHING;
    END IF;
    IF v_caught AND NOT EXISTS (SELECT 1 FROM public.catches c WHERE c.round_id = rec.round_id AND c.user_id = rec.user_id) THEN
      v_level := coalesce(private.encounter_pokemon_level(r.dex, r.id), 5);
      v_mat := private.materialize_streamlink_catch(
        rec.user_id,
        form_id,
        v_level,
        'catch',
        'play:' || rec.round_id::text || ':' || rec.user_id::text,
        rec.ball,
        rec.round_id,
        private.variant_is_shiny(r.variant),
        'sl-ref-20261013-227b573',
        NULL,
        r.variant,
        species,
        r.gender
      );
      IF coalesce(v_mat->>'ok', 'false') IS DISTINCT FROM 'true' THEN
        IF coalesce((v_mat->>'replay')::boolean, false)
           OR coalesce(v_mat->'errors', '[]'::jsonb) ? 'already-settled' THEN
          IF NOT EXISTS (
            SELECT 1 FROM public.catches c
            WHERE c.round_id = rec.round_id AND c.user_id = rec.user_id
          ) THEN
            RAISE EXCEPTION 'wire-materialize-failed: already-settled-without-catch';
          END IF;
        ELSE
          RAISE EXCEPTION 'wire-materialize-failed: %', coalesce(v_mat->>'errors', v_mat::text);
        END IF;
      END IF;
      IF coalesce(v_mat->>'ok', 'false') = 'true' THEN
        BEGIN
          v_catch_id := NULL;
          v_life := NULL;
          IF nullif(btrim(v_mat->>'catchId'), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            v_catch_id := (v_mat->>'catchId')::uuid;
          END IF;
          IF v_catch_id IS NOT NULL THEN
            SELECT a.lifecycle INTO v_life
            FROM private.species_mastery_activation AS a
            WHERE a.singleton
            FOR SHARE;
            IF v_life IN ('active', 'paused') THEN
              PERFORM private.note_species_mastery_catch(v_catch_id);
            END IF;
          END IF;
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END IF;
    END IF;
  END LOOP;
  UPDATE public.encounter_rounds SET resolved = true, paused_at = null, last_action = coalesce(throw_line, last_action, 'Results locked in'), updated_at = now() WHERE id = r.id RETURNING * INTO r;
  RETURN r;
END;
$function$

CREATE OR REPLACE FUNCTION private.spend_bag_item(p_uid uuid, p_item text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  spent int;
BEGIN
  IF p_item = 'berry' THEN
    UPDATE public.inventories SET berry = berry - 1, updated_at = now()
      WHERE user_id = p_uid AND berry > 0;
  ELSIF p_item = 'bait' THEN
    UPDATE public.inventories SET bait = bait - 1, updated_at = now()
      WHERE user_id = p_uid AND bait > 0;
  ELSIF p_item = 'pokeball' THEN
    UPDATE public.inventories SET pokeball = pokeball - 1, updated_at = now()
      WHERE user_id = p_uid AND pokeball > 0;
  ELSIF p_item = 'greatball' THEN
    UPDATE public.inventories SET greatball = greatball - 1, updated_at = now()
      WHERE user_id = p_uid AND greatball > 0;
  ELSIF p_item = 'ultraball' THEN
    UPDATE public.inventories SET ultraball = ultraball - 1, updated_at = now()
      WHERE user_id = p_uid AND ultraball > 0;
  ELSIF private.is_capture_berry(p_item) THEN
    UPDATE public.inventories
      SET berries = jsonb_set(
            coalesce(berries, '{}'::jsonb),
            ARRAY[p_item],
            to_jsonb(coalesce((berries->>p_item)::int, 0) - 1)
          ),
          updated_at = now()
      WHERE user_id = p_uid
        AND coalesce((berries->>p_item)::int, 0) > 0;
  ELSIF p_item = ANY (private.extra_ball_keys()) THEN
    UPDATE public.inventories
      SET balls = jsonb_set(
            coalesce(balls, '{}'::jsonb),
            ARRAY[p_item],
            to_jsonb(coalesce((balls->>p_item)::int, 0) - 1)
          ),
          updated_at = now()
      WHERE user_id = p_uid
        AND coalesce((balls->>p_item)::int, 0) > 0;
  ELSE
    RAISE EXCEPTION 'Unknown item.';
  END IF;
  GET DIAGNOSTICS spent = ROW_COUNT;
  IF spent = 0 THEN
    RAISE EXCEPTION 'You have no % left. No item spent.', private.item_label(p_item)
      USING ERRCODE = 'NB001';
  END IF;
  INSERT INTO public.item_ledger (user_id, item_key, amount, reason, source_id, idempotency)
  VALUES (
    p_uid, p_item, -1, 'BAG_SPEND', NULL,
    'bag-spend:' || p_uid::text || ':' || p_item || ':' || gen_random_uuid()::text
  );
END;
$function$
